def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_unknown_customer(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_empty_for_customer_without_orders(shop):
    assert shop.insights.handle_order_history("c1").body == {"customer_id": "c1", "orders": []}


def test_order_history_newest_first_including_cancelled(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 1))
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    third = order(shop, "c1", ("LAMP", 1)).body["order_id"]
    shop.orders.handle_cancel(second)
    body = shop.insights.handle_order_history("c1").body
    assert body == {"customer_id": "c1", "orders": [
        {"order_id": third, "status": "placed", "total_cents": 6000},
        {"order_id": second, "status": "cancelled", "total_cents": 600},
        {"order_id": first, "status": "placed", "total_cents": 2500},
    ]}


def test_order_history_totals_match_order_summary_including_discount(shop):
    standard = order(shop, "c1", ("LAMP", 2)).body["order_id"]
    gold = order(shop, "c2", ("LAMP", 2)).body["order_id"]
    history = shop.insights.handle_order_history("c1").body["orders"]
    assert history[0]["order_id"] == standard
    assert history[0]["total_cents"] == shop.orders.handle_get(standard).body["total_cents"] == 10800
    gold_history = shop.insights.handle_order_history("c2").body["orders"]
    assert gold_history[0]["total_cents"] == shop.orders.handle_get(gold).body["total_cents"] == 10200

