"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.customer_service import CustomerService
from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int


class CustomerInsightsController:
    def __init__(self, orders: OrderService, customers: CustomerService) -> None:
        self._orders = orders
        self._customers = customers

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with the discounted total of each."""
        try:
            orders = self._orders.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        entries: list[dict[str, Any]] = [
            {"order_id": order.order_id, "status": order.status,
             "total_cents": self._orders.summarize(order).total_cents}
            for order in reversed(orders)  # service returns creation order; ids increase with it
        ]
        return Response(200, {"customer_id": customer_id, "orders": entries})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of a customer's orders, excluding cancelled ones."""
        try:
            count, total = self._lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": count,
                              "lifetime_value_cents": total})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers ranked by lifetime value, highest first (ties by customer_id).

        Customers with a lifetime value of zero are left out.
        """
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = []
        for customer in self._customers.list_all():
            _, total = self._lifetime_value(customer.customer_id)
            if total > 0:
                ranked.append((total, customer))
        ranked.sort(key=lambda pair: (-pair[0], pair[1].customer_id))
        entries = [{"customer_id": customer.customer_id, "name": customer.name,
                    "lifetime_value_cents": total}
                   for total, customer in ranked[:limit]]
        return Response(200, {"customers": entries})

    def _lifetime_value(self, customer_id: str) -> tuple[int, int]:
        """(number of non-cancelled orders, sum of their discounted totals).

        Raises CustomerNotFound for unknown customers.
        """
        orders = self._orders.list_for_customer(customer_id)
        active = [order for order in orders if order.status != "cancelled"]
        return len(active), sum(self._orders.summarize(order).total_cents for order in active)

